package lt.oneman.sync;
import java.util.*;
/** UTC-day observed progress only; reconnects never count offline XP. Saved per RS profile. */
final class CompanionDay {
    String day="";
    long xp;
    Map<String,Integer> gainedLevels=new LinkedHashMap<>(),lastLevels=new LinkedHashMap<>();
    Set<String> quests=new LinkedHashSet<>();
    private transient boolean baseline;
    private transient long lastXp;
    private transient Set<String> previousQuests=new HashSet<>();
    void resume(){baseline=false;}
    void observe(String utcDay,Map<String,Integer> levels,Set<String> done,long totalXp) {
        if(!utcDay.equals(day)) {day=utcDay;xp=0;gainedLevels.clear();lastLevels.clear();quests.clear();baseline=false;}
        if(baseline) {
            xp+=Math.max(0,totalXp-lastXp);
            for(String q:done)if(!previousQuests.contains(q))quests.add(q);
            levels.forEach((k,v)->{int delta=Math.max(0,v-lastLevels.getOrDefault(k,v));if(delta>0)gainedLevels.merge(k,delta,Integer::sum);});
        }
        lastLevels=new LinkedHashMap<>(levels);
        previousQuests=new HashSet<>(done);lastXp=totalXp;baseline=true;
    }
    String text(Map<String,CompanionPlanner.Step> catalog) {
        StringBuilder out=new StringBuilder("Today (UTC "+day+"): "+xp+" observed XP\n");
        gainedLevels.forEach((skill,gain)->out.append(skill).append(": +").append(gain).append(" observed levels (latest ").append(lastLevels.get(skill)).append(")\n"));
        quests.forEach(q->{if(catalog.containsKey(q))out.append("Quest: ").append(catalog.get(q).name).append("\n");});
        return out.toString();
    }
}

package lt.oneman.sync;

import com.google.gson.*;
import java.util.*;

/** Deterministic local view of the OneMan catalog. Never projects quest XP or gear ownership. */
final class CompanionPlanner {
    static final class Step {
        String id, name, type, wiki, completedByQuest;
        double rank; int qp, questPoints;
        boolean autoSkills;
        Map<String,Integer> skills = new LinkedHashMap<>();
        List<String> quests = new ArrayList<>();
        List<String> why = new ArrayList<>();
        public String toString() { return name; }
    }
    static final class Catalog { List<Step> nodes; Map<String,List<String>> methods; }
    final Map<String,Step> nodes = new LinkedHashMap<>();
    final List<Step> ordered;
    final Map<String,List<String>> methods;
    CompanionPlanner(Catalog data) {
        methods=data.methods==null?Collections.emptyMap():data.methods;
        ordered = new ArrayList<>(data.nodes);
        ordered.sort(Comparator.comparingDouble(n -> n.rank));
        ordered.forEach(n -> nodes.put(n.id,n));
    }
    List<Step> plan(Map<String,Integer> levels, Set<String> completed, Set<String> manual, int qp) {
        List<Step> out = new ArrayList<>(); Set<String> visited = new HashSet<>();
        for (Step n : ordered) {
            if (n.id.startsWith("MAX_")) continue; // Maxing is a separate long-term goal, not an early next step.
            visit(n, levels, completed, manual, qp, visited, out);
        }
        return out;
    }
    Step trainingFromId(String id) {
        if(!id.startsWith("TRAIN_"))return null;
        int split=id.lastIndexOf('_');if(split<=6)return null;
        String skill=id.substring(6,split);if(!methods.containsKey(skill))return null;
        try{int level=Integer.parseInt(id.substring(split+1));if(level<2||level>99)return null;
            Step step=new Step();step.id=id;step.type="training";step.name=skill+" → "+level;
            step.skills.put(skill,level);step.wiki="https://oldschool.runescape.wiki/w/"+skill;return step;
        }catch(NumberFormatException ignored){return null;}
    }
    List<Step> forGoal(Step goal,Map<String,Integer> levels,Set<String> done,Set<String> confirmed,int qp) {
        List<Step> steps=new ArrayList<>();visit(goal,levels,done,confirmed,qp,new HashSet<>(),steps);return steps;
    }
    private void visit(Step n, Map<String,Integer> levels, Set<String> done, Set<String> manual,
        int qp, Set<String> visited, List<Step> out) {
        if (!visited.add(n.id) || done.contains(n.id) || manual.contains(n.id)
            || n.completedByQuest != null && done.contains(n.completedByQuest)) return;
        if (n.autoSkills && n.skills.entrySet().stream().allMatch(e -> levels.containsKey(e.getKey()) && levels.get(e.getKey()) >= e.getValue())) return;
        for (String q : n.quests) { Step prior = nodes.get(q); if (prior != null) visit(prior,levels,done,manual,qp,visited,out); }
        for (Map.Entry<String,Integer> e : n.skills.entrySet()) {
            Integer have = levels.get(e.getKey());
            if (!n.autoSkills && !"training".equals(n.type) && (have == null || have < e.getValue())) {
                String id = "TRAIN_"+e.getKey()+"_"+e.getValue();
                if (visited.add(id)) {
                    if (e.getKey().equals("Herblore") && nodes.containsKey("DRUIDIC_RITUAL")) visit(nodes.get("DRUIDIC_RITUAL"),levels,done,manual,qp,visited,out);
                    Step training = new Step(); training.id=id; training.type="training";
                    training.name=e.getKey()+" → "+e.getValue(); training.skills.put(e.getKey(),e.getValue());
                    List<String> method=methods.getOrDefault(e.getKey(),Arrays.asList("Pasirink prieinamą training metodą.","Choose an accessible training method."));
                    training.why=Arrays.asList("Reikia tikslui: "+n.name+". "+method.get(0),"Needed for: "+n.name+". "+method.get(Math.min(1,method.size()-1)));
                    training.wiki="https://oldschool.runescape.wiki/w/"+e.getKey(); out.add(training);
                }
            }
        }
        out.add(n);
    }
    String requirements(Step n, Map<String,Integer> levels, Set<String> done, int qp) {
        StringBuilder s=new StringBuilder();
        n.skills.forEach((k,v)->s.append(k).append(": ").append(levels.containsKey(k)?levels.get(k):"unknown").append(" / ").append(v).append("\n"));
        for(String q:n.quests) s.append(done.contains(q)?"✓ ":"Missing quest: ").append(nodes.containsKey(q)?nodes.get(q).name:q).append("\n");
        if(n.qp>0)s.append("Quest points: ").append(qp).append(" / ").append(n.qp).append("\n");
        s.append("Check supplies and encounters; this is not a combat-readiness claim.");
        return s.toString();
    }
}

package lt.oneman.sync;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.Filepath;
import okhttp3.*;

/** Explicit opt-in passive screenshots; bounded work, no automatic retries or input. */
@Singleton
final class CompanionScreenshots {
    interface Directory { Filepath get() throws IOException; }
    @Inject private DrawManager draws;
    @Inject private OneManSyncConfig config;
    @Inject private OkHttpClient http;
    private volatile boolean active;
    private volatile String last="Capture is opt-in. Enable Save milestone screenshots in plugin settings. Upload has a separate opt-in.\nImages contain the visible game window. Local screenshots remain on your computer.";
    private Directory directory;
    private ExecutorService worker;
    private final Set<Call> calls=ConcurrentHashMap.newKeySet();
    private final AtomicInteger pending=new AtomicInteger();
    private volatile int generation;
    void start(Directory d) { directory=d;generation++;active=true;pending.set(0);worker=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"OneMan screenshots");t.setDaemon(true);return t;}); }
    void stop() { active=false;generation++;calls.forEach(Call::cancel);calls.clear();if(worker!=null)worker.shutdownNow(); }
    String status() { return last; }
    void capture(String player,String profile,String milestone) {
        if(!active||!config.milestoneScreenshots())return;
        if(pending.incrementAndGet()>3){pending.decrementAndGet();last="Screenshot queue full; this capture was skipped.";return;}
        final int epoch=generation;final long captured=System.currentTimeMillis();
        // Capture the consent and token for this player; never switch recipients later.
        final boolean upload=config.uploadMilestoneScreenshots()&&config.enabled();final String token=config.syncKey().trim();
        draws.requestNextFrameListener(image->{
            if(!active||epoch!=generation)return;
            BufferedImage copy=new BufferedImage(image.getWidth(null),image.getHeight(null),BufferedImage.TYPE_INT_RGB);
            Graphics2D g=copy.createGraphics();g.drawImage(image,0,0,null);g.dispose();
            try { worker.submit(()-> { try {
                if(!active||epoch!=generation||!config.milestoneScreenshots())return;
                ByteArrayOutputStream bytes=new ByteArrayOutputStream();ImageIO.write(copy,"png",bytes);
                byte[] png=bytes.toByteArray();
                String folder=UUID.nameUUIDFromBytes(profile.getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();
                Filepath dir=directory.get().join("screenshots",folder);dir.createDirectories();
                Filepath file=dir.joinSegment(captured+"-"+UUID.randomUUID()+".png");file.write(png);
                last="Saved: "+file+"\nMilestone: "+milestone+"\n"+(upload?"Upload queued.":"Local only.");
                if(upload&&!token.isEmpty()&&active&&epoch==generation&&config.uploadMilestoneScreenshots()&&config.enabled()&&config.syncKey().trim().equals(token))send(png,player,milestone,captured,token,epoch);
            } catch(IOException | RuntimeException error) { last="Screenshot could not be saved. No upload was sent."; }
            finally { if(epoch==generation)pending.decrementAndGet(); } }); }
            catch(RejectedExecutionException ignored) { if(epoch==generation)pending.decrementAndGet(); }
        });
    }
    private void send(byte[] png,String player,String milestone,long captured,String token,int epoch) {
        if(png.length>5*1024*1024){last+="\nUpload skipped: image exceeds 5 MB. Local copy retained.";return;}
        MultipartBody body=new MultipartBody.Builder().setType(MultipartBody.FORM)
            .addFormDataPart("player",player).addFormDataPart("milestone",milestone)
            .addFormDataPart("capturedEpochMs",Long.toString(captured))
            .addFormDataPart("screenshot","milestone.png",RequestBody.create(MediaType.parse("image/png"),png)).build();
        Call call=http.newCall(new Request.Builder().url("https://oneman.lt/runelite_memory_upload.php")
            .header("Authorization","Bearer "+token).post(body).build());calls.add(call);
        if(!active||epoch!=generation){calls.remove(call);call.cancel();return;}
        call.enqueue(new Callback(){
            public void onFailure(Call c,IOException error) { calls.remove(c);if(active&&epoch==generation)last+="\nUpload failed; local copy retained. No automatic retry."; }
            public void onResponse(Call c,Response response) { try(Response r=response){if(active&&epoch==generation)last+=r.isSuccessful()?"\nUploaded to OneMan.":"\nOneMan rejected upload (HTTP "+r.code()+"); local copy retained.";}finally{calls.remove(c);} }
        });
    }
}

package lt.oneman.sync;
import java.util.*;
/** Curated quest start items. Check the linked quest guide for stage-specific extras. */
final class CompanionSupplies {
    static List<String> forStep(CompanionPlanner.Step s){
        if(s==null)return Collections.emptyList();
        switch(s.id){
            case "COOKS_ASSISTANT":return Arrays.asList("Bucket of milk","Egg","Pot of flour");
            case "DORICS_QUEST":return Arrays.asList("Clay","Copper ore","Iron ore");
            case "DRUIDIC_RITUAL":return Arrays.asList("Raw beef","Raw bear meat","Raw rat meat","Raw chicken");
            case "SHEEP_SHEARER":return Arrays.asList("Ball of wool");
            case "GOBLIN_DIPLOMACY":return Arrays.asList("Goblin mail","Orange dye","Blue dye");
            case "CHRONICLE":return Arrays.asList("Chronicle","Teleport card");
            default:
                if("training".equals(s.type)){
                    if(s.skills.containsKey("Mining"))return Arrays.asList("Pickaxe");
                    if(s.skills.containsKey("Woodcutting"))return Arrays.asList("Axe");
                }
                return Collections.emptyList();
        }
    }
    static boolean hasChronicle(Map<String,Integer> inventory,Map<String,Integer> equipment,Map<String,Integer> bank) {
        return java.util.stream.Stream.of(inventory,equipment,bank).anyMatch(m->m.entrySet().stream().anyMatch(e->e.getValue()>0&&matches(e.getKey(),"Chronicle")));
    }
    static int quantity(CompanionPlanner.Step s,String need) {
        if(s==null)return 1;
        if(s.id.equals("DORICS_QUEST"))return need.equals("Clay")?6:need.equals("Copper ore")?4:2;
        if(s.id.equals("SHEEP_SHEARER"))return 20;
        if(s.id.equals("GOBLIN_DIPLOMACY")&&need.equals("Goblin mail"))return 3;
        return 1;
    }
    static boolean matches(String item,String need){
        item=item.toLowerCase(Locale.ROOT);need=need.toLowerCase(Locale.ROOT);
        return need.equals("pickaxe")?item.endsWith(" pickaxe"):need.equals("axe")?item.endsWith(" axe"):item.equals(need);
    }
}

package lt.oneman.sync;
import com.google.gson.*;
/** Shows only a bounded JSON error field, never an HTML page, response payload or sync token. */
final class CompanionSyncError {
    static String describe(Gson gson,String body) {
        try {
            JsonObject json=gson.fromJson(body,JsonObject.class);if(json==null||!json.has("error")||!json.get("error").isJsonPrimitive())return "";
            String error=json.get("error").getAsString().replaceAll("[\\r\\n\\x00-\\x1f]"," ")
                .replaceAll("(?i)Bearer\\s+\\S+","Bearer [redacted]").replaceAll("(?i)(token|password|syncKey)\\s*[:=]\\s*\\S+","$1=[redacted]");
            return " — "+error.substring(0,Math.min(240,error.length()));
        } catch(RuntimeException ignored){return "";}
    }
}

package lt.oneman.sync;
import java.awt.Point;
import javax.swing.*;
import javax.swing.text.DefaultCaret;
/** Keep passive updates from pulling readers back to the caret. Call on the EDT. */
final class CompanionText {
 private CompanionText() {}
 static void update(JTextArea area,String text) {
  if(area.getText().equals(text))return;
  JViewport viewport=(JViewport)SwingUtilities.getAncestorOfClass(JViewport.class,area);
  Point position=viewport==null?null:viewport.getViewPosition();
  ((DefaultCaret)area.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
  area.setText(text);
  if(viewport!=null) {
   viewport.setViewPosition(position);
   SwingUtilities.invokeLater(()->{if(area.getText().equals(text))viewport.setViewPosition(position);});
  }
 }
}

package lt.oneman.sync;
import java.util.*;
import net.runelite.api.Experience;
/** Goal-specific static plan, filtered using real levels, quest access and observed task. */
final class CompanionTraining {
    static boolean isSkill(CompanionPlanner.Step s){return s!=null&&s.skills.size()==1&&("training".equals(s.type)||"skill".equals(s.type));}
    static boolean achieved(CompanionPlanner.Step s,Map<String,Integer> levels,Set<String> quests,Set<String> unlocks) {
        return quests.contains(s.id)||unlocks.contains(s.id)||isSkill(s)&&s.skills.entrySet().stream().allMatch(e->levels.containsKey(e.getKey())&&levels.get(e.getKey())>=e.getValue());
    }
    static List<String> masters(int combat,int slayer,Set<String> quests) {
        List<String> choices=new ArrayList<>();
        if(combat>=100&&slayer>=50&&quests.contains("SHILO_VILLAGE"))choices.add("Duradel / Kuradal — Shilo Village");
        if(combat>=85)choices.add("Nieve / Steve — Gnome Stronghold");
        if(combat>=75)choices.add("Konar — Mount Karuulm; assignments restrict the location");
        if(combat>=70&&quests.contains("LOST_CITY"))choices.add("Chaeldar — Zanaris");
        if(combat>=40)choices.add("Vannaka — Edgeville Dungeon");
        choices.add("Turael / Spria — low-level tasks; check streak-reset rules before replacing a task");
        return choices;
    }
    static String describe(CompanionPlanner.Step s,Map<String,Integer> levels,Set<String> quests,int combat,String accountType,
        SlayerLabJournal.Session task,int slayerXp,Map<String,List<String>> methods) {
        if(!isSkill(s))return "";
        String skill=s.skills.keySet().iterator().next();int target=s.skills.get(skill);Integer current=levels.get(skill);
        StringBuilder text=new StringBuilder("Goal: "+skill+" "+target+"\nCurrent: "+(current==null?"unknown":current)+" / "+target+"\n");
        if(current!=null)text.append("Levels remaining: ").append(Math.max(0,target-current)).append("\n");
        text.append("Account: ").append(accountType).append(" · combat ").append(combat).append("\n\n");
        if(skill.equals("Slayer")) {
            text.append("XP remaining: ").append(Math.max(0,Experience.getXpForLevel(target)-slayerXp)).append("\n\n");
            if(task!=null&&task.ended==0)text.append("1. Continue your current task: ").append(task.task).append(" — ").append(task.remaining).append(" remaining.\nAssigned area: ").append(task.assignedArea==null||task.assignedArea.isEmpty()?"any eligible area":task.assignedArea).append("\n");
            else text.append("1. Obtain an assignment from an accessible Slayer master. Do not kill arbitrary monsters for Slayer XP.\n");
            text.append("2. Open OneMan → Slayer & Prayer for this task's places, cannon rules, protection and carried supplies.\n")
                .append("3. Complete tasks and return to your chosen master until ").append(target).append(" Slayer. Progress updates from real XP; task rolls are not predicted.\n\nEligible master options from known requirements:\n");
            masters(combat,current==null?0:current,quests).forEach(m->text.append("• ").append(m).append("\n"));
            text.append("\nCannon is optional: Dwarf Cannon completion, all parts, ammunition and a permitted chamber are needed. No ownership or cannonball quantity is assumed. Use your own supplies; Ironman accounts obtain them themselves.\n");
            if(task!=null)text.append("\nObserved session Slayer XP: ").append(task.slayerXp).append(". No completion-time estimate until a representative rate is observed.");
        } else {
            List<String> method=methods.get(skill);text.append("1. ").append(method==null||method.isEmpty()?"Choose an accessible training method in the skill guide.":method.get(method.size()>1?1:0))
                .append("\n2. Check that method's actual access and supplies; bank ownership and usable gear are separate.\n3. Train until ").append(target).append("; real levels update this target automatically.\n");
        }
        return text.toString();
    }
}

package lt.oneman.sync;
/** Legacy Karamja Easy/Medium/Hard use state 2; other diary completion bits use 1. */
final class DiaryCompletion {
 private DiaryCompletion() {}
 static boolean complete(String area,String tier,int value) {
  boolean legacy="Karamja".equalsIgnoreCase(area)&&("Easy".equals(tier)||"Medium".equals(tier)||"Hard".equals(tier));
  return value==(legacy?2:1);
 }
}

package lt.oneman.sync;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.LinkBrowser;

/** Passive, profile-scoped companion. All game reads are on the client thread. */
@Singleton
final class OneManCompanion {
    static final String VERSION = "0.7.2";
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ConfigManager configs;
    @Inject private Gson gson;
    @Inject private ItemManager items;
    @Inject private ClientToolbar toolbar;
    @Inject private OverlayManager overlays;
    @Inject private CompanionBankOverlay overlay;
    @Inject private SlayerLabAccount account;
    @Inject private OneManSlayerHelper slayerHelper;
    @Inject private OneManSyncConfig config;
    @Inject private CompanionScreenshots screenshots;
    private CompanionPlanner planner;
    private Panel panel;
    private NavigationButton navigation;
    private volatile boolean active;
    private String profile = "", selected = "", lastSummary = "No previous session recorded.";
    private boolean focusedGoal;
    private Set<String> observedUnlocks=new HashSet<>();
    private Set<String> manual = new HashSet<>(), completed = new HashSet<>(), startingQuests = new HashSet<>();
    private Map<String,Integer> levels = new LinkedHashMap<>(), startingLevels = new LinkedHashMap<>();
    private Map<String,Long> synced = new LinkedHashMap<>();
    private String syncStatus = "No successful upload in this session.";
    private long started, startingXp, ticks;
    private int loginDelay;
    private boolean baseline;
    private CompanionDay day=new CompanionDay();
    private long lastDaySave;
    private List<CompanionPlanner.Step> route = Collections.emptyList();
    private int qp;
    private String player = "";

    void startUp(CompanionScreenshots.Directory directory) {
        ticks=0;loginDelay=10;levels.clear();completed.clear();lastSession="No active session.";
        try (Reader r = new InputStreamReader(Objects.requireNonNull(getClass().getResourceAsStream("efficiency-catalog.json")), StandardCharsets.UTF_8)) {
            planner = new CompanionPlanner(gson.fromJson(r, CompanionPlanner.Catalog.class));
        } catch (IOException | RuntimeException error) { throw new IllegalStateException("Cannot load bundled OneMan roadmap", error); }
        active = true; baseline = false; profile = ""; synced.clear();
        screenshots.start(directory);
        overlays.add(overlay);
        SwingUtilities.invokeLater(() -> {
            if (!active) return;
            panel = new Panel();
            BufferedImage icon = new BufferedImage(24,24,BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = icon.createGraphics(); g.setColor(new Color(218,176,85));
            g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,18)); g.fillPolygon(new int[]{4,20,20,12,4},new int[]{3,3,13,22,13},5);
            g.setColor(new Color(38,42,48));g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,14));g.drawString("1",8,15);g.dispose();
            PluginPanel root=new PluginPanel(){};root.setLayout(new BorderLayout(0,6));
            JPanel cards=new JPanel(new CardLayout());cards.add(panel,"Overview");
            if(slayerHelper.companionPanel()!=null)cards.add(slayerHelper.companionPanel(),"Slayer");
            JComboBox<String> sections=new JComboBox<>(new String[]{"Overview","Slayer"});
            sections.addActionListener(event->((CardLayout)cards.getLayout()).show(cards,(String)sections.getSelectedItem()));
            root.add(sections,BorderLayout.NORTH);root.add(cards,BorderLayout.CENTER);
            navigation = NavigationButton.builder().tooltip("OneMan — Roadmap, Slayer").icon(icon).priority(6).panel(root).build();
            toolbar.addNavigation(navigation);
        });
    }
    void shutDown() {
        finish(); active=false; screenshots.stop(); overlays.remove(overlay); overlay.needed=Collections.emptySet();
        SwingUtilities.invokeLater(() -> { if(navigation!=null)toolbar.removeNavigation(navigation); navigation=null;panel=null; });
    }
    void onGameStateChanged(GameStateChanged e) {
        if(e.getGameState()==GameState.LOGGED_IN)loginDelay=10;
        if(e.getGameState()==GameState.LOGIN_SCREEN) { finish(); overlay.needed=Collections.emptySet(); baseline=false; levels.clear();completed.clear(); showLoggedOut(); }
    }
    void onGameTick(GameTick e) {
        if(!active || client.getGameState()!=GameState.LOGGED_IN || client.getLocalPlayer()==null) return;
        if(loginDelay>0){loginDelay--;return;}
        if(++ticks%5!=0) return;
        String key=configs.getRSProfileKey(); if(key==null || key.isEmpty())return;
        if(!key.equals(profile)) {
            finish(); profile=key; baseline=false; synced.clear();syncStatus="No successful upload in this session.";
            manual.clear();observedUnlocks.clear();selected="";focusedGoal=false;
            try { String savedDay=configs.getConfiguration("one-man-sync",profile,"companionDay");day=savedDay==null?new CompanionDay():gson.fromJson(savedDay,CompanionDay.class);if(day==null||day.gainedLevels==null||day.lastLevels==null||day.quests==null)day=new CompanionDay(); } catch(RuntimeException ignored) {day=new CompanionDay();}
            day.resume();
            try { String saved=configs.getConfiguration("one-man-sync",profile,"companionManual");
                if(saved!=null)manual.addAll(Arrays.asList(gson.fromJson(saved,String[].class))); } catch(RuntimeException ignored) { manual.clear(); }
            try{String unlocks=configs.getConfiguration("one-man-sync",profile,"companionObservedUnlocks");if(unlocks!=null)observedUnlocks.addAll(Arrays.asList(gson.fromJson(unlocks,String[].class)));}catch(RuntimeException ignored){observedUnlocks.clear();}
            focusedGoal=Boolean.parseBoolean(configs.getConfiguration("one-man-sync",profile,"companionFocus"));
            String goal=configs.getConfiguration("one-man-sync",profile,"companionGoal"); if(goal!=null)selected=goal;
            String summary=configs.getConfiguration("one-man-sync",profile,"companionSummary");lastSummary=summary==null?"No previous session recorded.":summary;
        }
        player=client.getLocalPlayer().getName();
        if(!baseline)day.resume();
        Map<String,Integer> nextLevels=new LinkedHashMap<>();
        for(Skill skill:Skill.values())if(skill!=Skill.OVERALL)nextLevels.put(skill.getName(),client.getRealSkillLevel(skill));
        Set<String> nextQuests=new HashSet<>();
        for(Quest q:Quest.values())try { if(q.getState(client)==QuestState.FINISHED) {
            nextQuests.add(q.name());
            for(CompanionPlanner.Step n:planner.ordered)if(normal(n.name).equals(normal(q.getName())))nextQuests.add(n.id);
        }}catch(RuntimeException ignored) { /* Unknown state remains incomplete. */ }
        if(baseline) {
            nextQuests.addAll(completed);
            for(String q:nextQuests)if(!completed.contains(q)&&planner.nodes.containsKey(q))screenshots.capture(player,profile,"Quest: "+planner.nodes.get(q).name);
            nextLevels.forEach((skill,level)-> { if(level>=99 && levels.getOrDefault(skill,99)<99)screenshots.capture(player,profile,skill+" 99"); });
        }
        levels=nextLevels;completed=nextQuests;
        if(!baseline) { baseline=true;started=System.currentTimeMillis();startingXp=client.getOverallExperience();startingLevels=new LinkedHashMap<>(levels);startingQuests=new HashSet<>(completed); }
        day.observe(java.time.LocalDate.now(java.time.ZoneOffset.UTC).toString(),levels,completed,client.getOverallExperience());
        if(System.currentTimeMillis()-lastDaySave>30000){saveDay();}
        if(CompanionSupplies.hasChronicle(container(InventoryID.INV),container(InventoryID.WORN),profile.equals(account.profile)?account.bank.items:Collections.emptyMap())) {
            if(observedUnlocks.add("CHRONICLE"))configs.setConfiguration("one-man-sync",profile,"companionObservedUnlocks",gson.toJson(observedUnlocks));
        }
        Set<String> confirmed=new HashSet<>(manual);confirmed.addAll(observedUnlocks);
        qp=Math.max(0,client.getVarpValue(VarPlayerID.QP));
        route=planner.plan(levels,completed,confirmed,qp);
        CompanionPlanner.Step chosen=goal();
        if(chosen!=null&&CompanionTraining.achieved(chosen,levels,completed,confirmed)) {
            focusedGoal=false;selected="";configs.setConfiguration("one-man-sync",profile,"companionFocus",false);
        }
        if(selected.isEmpty() && !route.isEmpty())selected=route.get(0).id;
        render();
    }
    private static String normal(String s) { return s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]",""); }
    private CompanionPlanner.Step goal() {
        for(CompanionPlanner.Step s:route)if(s.id.equals(selected))return s;
        CompanionPlanner.Step catalog=planner.nodes.get(selected);
        return catalog!=null?catalog:planner.trainingFromId(selected);
    }
    private Map<String,Integer> container(int id) {
        Map<String,Integer> map=new LinkedHashMap<>();ItemContainer c=client.getItemContainer(id);
        if(c!=null)for(Item item:c.getItems())if(item.getId()>=0&&item.getQuantity()>0) {
            ItemComposition composition=items.getItemComposition(item.getId());
            // Noted items cannot be used as quest supplies until unnoted.
            if(composition.getNote()!=-1)continue;
            map.merge(composition.getName(),item.getQuantity(),Integer::sum);
        }
        return map;
    }
    private String preparation(CompanionPlanner.Step s) {
        Map<String,Integer> inv=container(InventoryID.INV),equipment=container(InventoryID.WORN);
        List<String> required=CompanionSupplies.forStep(s);StringBuilder text=new StringBuilder();
        boolean same=profile.equals(account.profile);
        if(CompanionTraining.isSkill(s))text.append(training(s)).append("\n\n");
        Set<Integer> ids=new HashSet<>(); ItemContainer bank=client.getItemContainer(InventoryID.BANK);
        for(String need:required) {
            int carried=count(inv,need), worn=count(equipment,need), stored=same?count(account.bank.items,need):0;
            text.append(need).append("\nInventory: ").append(carried).append(" | equipped: ").append(worn)
                .append(" | bank: ").append(same&&account.bank.seen>0?stored:"unknown").append("\n");
            int quantity=CompanionSupplies.quantity(s,need);
            text.append(carried+worn>=quantity?"READY":stored+carried+worn>=quantity?"TAKE FROM BANK":"MISSING / bank unknown")
                .append(" — need ").append(quantity).append("\n\n");
            if(bank!=null)for(Item item:bank.getItems())if(item.getId()>=0&&item.getQuantity()>0&&CompanionSupplies.matches(items.getItemComposition(item.getId()).getName(),need))ids.add(item.getId());
        }
        overlay.needed=Collections.unmodifiableSet(ids);
        if(required.isEmpty()&&!CompanionTraining.isSkill(s))text.append("No verified supply checklist for this goal yet. Open the guide; no readiness is inferred.\n");
        if(!required.isEmpty())text.append("Starting items only. Guide: extra supplies and charges. Bank counts may be outdated.");
        return text.toString();
    }
    private String training(CompanionPlanner.Step s) {
        SlayerLabJournal.Session task=profile.equals(account.profile)?account.journal.active:null;
        return CompanionTraining.describe(s,levels,completed,client.getLocalPlayer().getCombatLevel(),client.getAccountType().toString(),task,
            client.getSkillExperience(Skill.SLAYER),planner.methods);
    }
    private static int count(Map<String,Integer> map,String need) { return map.entrySet().stream().filter(e->CompanionSupplies.matches(e.getKey(),need)).mapToInt(Map.Entry::getValue).sum(); }
    private String summary() {
        StringBuilder text=new StringBuilder(day.text(planner.nodes)+"\nSession started: "+Instant.ofEpochMilli(started)+"\n");
        text.append("Observed XP: ").append(Math.max(0,client.getOverallExperience()-startingXp)).append("\n");
        levels.forEach((s,l)-> { int before=startingLevels.getOrDefault(s,l);if(l>before)text.append(s).append(": ").append(before).append(" → ").append(l).append("\n"); });
        for(CompanionPlanner.Step n:planner.ordered)if(completed.contains(n.id)&&!startingQuests.contains(n.id))text.append("Quest: ").append(n.name).append("\n");
        CompanionPlanner.Step next=goal();text.append("\nContinue next time: ").append(next==null?"choose a goal":next.name);
        if(profile.equals(account.profile)) {
            List<SlayerLabJournal.Session> sessions=new ArrayList<>(account.journal.history);
            if(account.journal.active!=null)sessions.add(account.journal.active);
            int credits=0,kills=0,xp=0;Map<String,Integer> loot=new TreeMap<>();
            for(SlayerLabJournal.Session session:sessions)if(session.started>=started) {credits+=session.credits;kills+=session.kills;xp+=session.slayerXp;session.loot.forEach((k,v)->loot.merge(k,v,Integer::sum));}
            text.append("\nSession Slayer: ").append(credits).append(" credits, ").append(kills).append(" attributed kills, ").append(xp).append(" XP\nObserved loot: ").append(loot);
        }
        text.append("\nOnly progress observed while this plugin was running is counted.");return text.toString();
    }
    private void finish() {
        if(!baseline||profile.isEmpty())return;
        // Use last sampled XP on logout; the client may already be resetting.
        lastSummary=lastSession;
        configs.setConfiguration("one-man-sync",profile,"companionSummary",lastSummary);
        saveDay();day.resume();
        baseline=false;
    }
    private void saveDay(){if(!profile.isEmpty()){configs.setConfiguration("one-man-sync",profile,"companionDay",gson.toJson(day));lastDaySave=System.currentTimeMillis();}}
    private String lastSession="No active session.";
    void syncResult(String sentProfile,JsonObject snapshot,boolean success,String status) {
        clientThread.invokeLater(() -> {
            if(!active||!profile.equals(sentProfile))return;
            syncStatus=status;
            if(success) {
                long now=System.currentTimeMillis();
                if(snapshot.has("skills"))synced.put("Skills",now);
                if(snapshot.has("quests"))synced.put("Quests",now);
                if(snapshot.has("slayer")&&snapshot.get("slayer").isJsonObject()&&snapshot.getAsJsonObject("slayer").has("lastTaskSeenEpochMs")
                    && snapshot.getAsJsonObject("slayer").get("lastTaskSeenEpochMs").getAsLong()>0)synced.put("Slayer",now);
                if(snapshot.has("bankSnapshotComplete")&&snapshot.get("bankSnapshotComplete").getAsBoolean())synced.put("Bank",snapshot.get("bankSnapshotEpochMs").getAsLong());
            }
        });
    }
    private void render() {
        CompanionPlanner.Step selectedGoal=goal();
        Set<String> confirmed=new HashSet<>(manual);confirmed.addAll(observedUnlocks);
        List<CompanionPlanner.Step> visible=focusedGoal&&selectedGoal!=null?planner.forGoal(selectedGoal,levels,completed,confirmed,qp):route;
        StringBuilder next=new StringBuilder("Player: "+player+" · "+client.getAccountType()+"\nCombat: "+client.getLocalPlayer().getCombatLevel()+" · Live quest points: "+qp+"\n");
        next.append(focusedGoal&&selectedGoal!=null?"Selected goal: "+selectedGoal.name:"Default OneMan route").append("\n");
        if(observedUnlocks.contains("CHRONICLE"))next.append("Chronicle ownership observed — obtain step skipped. Check remaining charges separately.\n");
        next.append("\n");
        if(focusedGoal&&CompanionTraining.isSkill(selectedGoal))next.append(training(selectedGoal)).append("\n\n");
        int index=0;for(CompanionPlanner.Step s:visible) {
            if(++index>3)break;next.append(index).append(". ").append(s.name).append("\n")
                .append(planner.requirements(s,levels,completed,qp)).append("\nWhy now: ")
                .append(s.why.isEmpty()?"Next in the selected route":s.why.get(config.companionLanguage().equalsIgnoreCase("LT")?0:Math.min(1,s.why.size()-1))).append("\n\n");
        }
        String prep=preparation(selectedGoal);
        SlayerLabJournal.Session session=profile.equals(account.profile)?account.journal.active:null;
        if(session==null&&profile.equals(account.profile)&&!account.journal.history.isEmpty())session=account.journal.history.get(0);
        String slayer=SlayerLabJournal.metrics(session,System.currentTimeMillis());
        if(session!=null)slayer+="\nStatus: "+session.status+"\n";
        if(session!=null)slayer+="\nRemaining: "+session.remaining+"\nStarted: "+Instant.ofEpochMilli(session.started)+"\nObserved loot: "+session.loot;
        StringBuilder fresh=new StringBuilder("Plugin: "+VERSION+"\n"+syncStatus+"\n\n");
        for(String key:Arrays.asList("Skills","Slayer","Bank","Quests"))fresh.append(key).append(": ").append(synced.containsKey(key)?Instant.ofEpochMilli(synced.get(key)):"not uploaded / unknown").append("\n");
        fresh.append("\nBank time is when the bank snapshot was captured; other times are successful uploads. A successful sync is not a promise that every field changed.\n");
        lastSession=summary();String currentSummary=lastSession+"\n\nPrevious session:\n"+lastSummary;
        List<CompanionPlanner.Step> choices=new ArrayList<>(route);for(CompanionPlanner.Step s:planner.ordered)if(choices.stream().noneMatch(n->n.id.equals(s.id)))choices.add(s);
        String nextText=next.toString(),slayerText=slayer,freshText=fresh.toString(),goalId=selected;
        SwingUtilities.invokeLater(() -> { if(active&&panel!=null)panel.update(nextText,prep,slayerText,freshText,currentSummary,choices,goalId,screenshots.status()); });
    }
    private void showLoggedOut() {
        SwingUtilities.invokeLater(()-> { if(active&&panel!=null) { panel.next.setText("Log in to calculate your next steps.");panel.prep.setText("Log in and open your bank.");panel.summary.setText(lastSummary);panel.slayer.setText("Logged out. The last observed Slayer session is archived in OneMan → Slayer → History."); } });
    }
    private final class Panel extends PluginPanel {
        final JTextArea next=area(),prep=area(),slayer=area(),fresh=area(),summary=area(),memories=area();
        final JComboBox<CompanionPlanner.Step> goals=new JComboBox<>();boolean updating;
        Panel() {
            setLayout(new BorderLayout());JTabbedPane tabs=new JTabbedPane();
            tabs.addTab("Next",new JScrollPane(next));
            JPanel preparation=new JPanel(new BorderLayout());preparation.add(goals,BorderLayout.NORTH);preparation.add(new JScrollPane(prep),BorderLayout.CENTER);
            JPanel actions=new JPanel(new GridLayout(0,1));JButton guide=new JButton("Open goal guide"),mark=new JButton("Confirm manual unlock"),capture=new JButton("Save progress screenshot");
            JButton reset=new JButton("Follow default roadmap");actions.add(reset);
            reset.addActionListener(e->clientThread.invokeLater(()->{focusedGoal=false;selected="";configs.setConfiguration("one-man-sync",profile,"companionFocus",false);}));
            actions.add(guide);actions.add(mark);preparation.add(actions,BorderLayout.SOUTH);tabs.addTab("Prep",preparation);
            tabs.addTab("Slayer",new JScrollPane(slayer));tabs.addTab("Sync",new JScrollPane(fresh));
            JPanel memoryPanel=new JPanel(new BorderLayout());memoryPanel.add(new JScrollPane(memories),BorderLayout.CENTER);memoryPanel.add(capture,BorderLayout.SOUTH);tabs.addTab("Memories",memoryPanel);
            tabs.addTab("Summary",new JScrollPane(summary));add(tabs,BorderLayout.CENTER);
            goals.addActionListener(e-> { if(updating)return;CompanionPlanner.Step s=(CompanionPlanner.Step)goals.getSelectedItem();if(s!=null)clientThread.invokeLater(()-> { if(!baseline)return;selected=s.id;focusedGoal=true;configs.setConfiguration("one-man-sync",profile,"companionFocus",true);configs.setConfiguration("one-man-sync",profile,"companionGoal",selected);render(); }); });
            guide.addActionListener(e-> { CompanionPlanner.Step s=(CompanionPlanner.Step)goals.getSelectedItem();if(s!=null&&s.wiki!=null&&s.wiki.startsWith("https://oldschool.runescape.wiki/"))LinkBrowser.browse(s.wiki); });
            mark.addActionListener(e->clientThread.invokeLater(()-> { CompanionPlanner.Step s=goal();if(baseline&&s!=null&&"unlock".equals(s.type)) {manual.add(s.id);configs.setConfiguration("one-man-sync",profile,"companionManual",gson.toJson(manual));selected="";} }));
            capture.addActionListener(e->clientThread.invokeLater(()-> { if(baseline)screenshots.capture(player,profile,"Progress"); }));
        }
        void update(String n,String p,String s,String f,String sum,List<CompanionPlanner.Step> choices,String id,String status) {
            CompanionText.update(next,n);CompanionText.update(prep,p);CompanionText.update(slayer,s);CompanionText.update(fresh,f);CompanionText.update(summary,sum);CompanionText.update(memories,status);
            CompanionPlanner.Step old=(CompanionPlanner.Step)goals.getSelectedItem();
            if(old==null||!old.id.equals(id)||goals.getItemCount()!=choices.size()) {
                updating=true;goals.removeAllItems();for(CompanionPlanner.Step choice:choices) {goals.addItem(choice);if(choice.id.equals(id))goals.setSelectedItem(choice);}updating=false;
            }
        }
    }
    private static JTextArea area() { JTextArea a=new JTextArea();a.setEditable(false);a.setLineWrap(true);a.setWrapStyleWord(true);a.setMargin(new Insets(8,8,8,8));return a; }
}

package lt.oneman.sync;

import java.util.function.BiConsumer;
import java.util.function.Function;
import net.runelite.client.config.ConfigManager;

/** Copies old Lab preferences without replacing existing Sync preferences.
 * Account journals and bank snapshots deliberately retain their original profile keys. */
final class OneManConfigMigration
{
    private static final String[] KEYS = {"combatStyle", "foodWarning", "doseWarning", "ammoWarning",
        "runeWarning", "notifySupplies", "prayerPointsWarning", "prayerDosesWarning", "notifyPrayer"};
    private OneManConfigMigration() {}

    static void migrate(ConfigManager manager)
    {
        migrate(key -> manager.getConfiguration(SlayerLabConfig.GROUP, key),
            key -> manager.getConfiguration("one-man-sync", key),
            (key, value) -> manager.setConfiguration("one-man-sync", key, value));
    }

    static void migrate(Function<String, String> legacy, Function<String, String> current,
        BiConsumer<String, String> save)
    {
        if ("true".equals(current.apply("labPreferencesMigrated"))) return;
        for (String key : KEYS)
        {
            String value = legacy.apply(key);
            if (value != null && current.apply(key) == null) save.accept(key, value);
        }
        save.accept("labPreferencesMigrated", "true");
    }
}

