        void showLocations(java.util.List<SlayerLabLocations.Destination> locations)
        {
            if (shown.equals(locations)) return;
            shown = locations;
            choices.removeAllItems();
            for (SlayerLabLocations.Destination destination : locations) choices.addItem(destination);
            boolean hasLocations = !locations.isEmpty();
            choices.setEnabled(hasLocations);locationWiki.setEnabled(hasLocations);
            SlayerLabLocations.Destination choice=(SlayerLabLocations.Destination)choices.getSelectedItem();
            boolean pin=choice!=null&&choice.entrance!=null;
            centre.setEnabled(pin);
            track.setEnabled(pin);
            clear.setEnabled(hasLocations);
            if (!hasLocations) access.setText("No mapped entrance available.");
        }
        void showTabs(String[] views,String task,String sessionNote,long started,String profile)
        {
            updating=true;
            shownProfile=profile;
            if(shownSession!=started) { shownSession=started; note.setText(sessionNote); }
            if(!shownTask.equals(task)) {
                shownTask=task; variants.removeAllItems(); for(String option:SlayerLabAdvice.variants(task)) variants.addItem(option);
                goals.removeAllItems(); for(SlayerLabAdvice.Goal option:SlayerLabAdvice.goals(task)) goals.addItem(option.item);
                goals.getEditor().setItem(goal); note.setText(sessionNote);
            }
            for(int i=0;i<sections.length;i++) CompanionText.update(sections[i],views[i]);
            url=SlayerLabCatalog.wiki(task); wiki.setEnabled(true); updating=false;
        }
        void showView(String view, String link)
        {
            updating=true; shownTask=""; shownProfile=""; shownSession=0;
            for(int i=0;i<8;i++) sections[i].setText(view);
            variants.removeAllItems(); goals.removeAllItems(); note.setText("");
            url = link;
            wiki.setEnabled(!link.isEmpty()); updating=false;
        }
    }
}

package lt.oneman.sync;

import com.google.gson.JsonObject;

/** Bounded label fallback; live counts, rewards and points always win. */
final class OneManSlayerState
{
    static final long LABEL_GRACE_MS=120000;
    static JsonObject reconcile(JsonObject current,JsonObject previous,long now)
    {
        if(previous==null || bool(current,"taskSignalValid")) return current;
        int target=integer(current,"rawTaskTarget");
        int count=integer(current,"rawTaskCount");
        long seen=number(previous,"lastTaskSeenEpochMs");
        boolean same=target>0 && target==integer(previous,"rawTaskTarget")
            && integer(current,"rawTaskArea")==integer(previous,"rawTaskArea")
            && integer(current,"initialAmount")==integer(previous,"initialAmount");
        boolean recent=seen>0 && now>=seen && now-seen<=LABEL_GRACE_MS;
        if(count>0 && count<=integer(previous,"amount") && same && recent
            && !string(previous,"taskName").isEmpty())
        {
            current.addProperty("taskName",string(previous,"taskName"));
            current.addProperty("location",string(previous,"location"));
            current.addProperty("amount",count);
            current.addProperty("taskSource","last-known");
            current.addProperty("taskStatus","last-known");
            current.addProperty("lastTaskSeenEpochMs",seen);
        }
        return current;
    }
    private static boolean bool(JsonObject o,String key)
    { try { return o.has(key) && o.get(key).getAsBoolean(); } catch(RuntimeException e) { return false; } }
    private static String string(JsonObject o,String key)
    { try { return o.has(key)?o.get(key).getAsString():""; } catch(RuntimeException e) { return ""; } }
    private static int integer(JsonObject o,String key) { return (int)number(o,key); }
    private static long number(JsonObject o,String key)
    { try { return o.has(key)?o.get(key).getAsLong():0; } catch(RuntimeException e) { return 0; } }
}

