final class SlayerLabSupplies
{
    static final class Counts
    {
        int food, doses, ammo, runes;
        final Map<String, Integer> potions = new TreeMap<>();
        final Map<String, Integer> runeStacks = new TreeMap<>();
        String warnings(SlayerLabConfig config)
        {
            List<String> warnings = new ArrayList<>();
            if (config.foodWarning() > 0 && food < config.foodWarning()) warnings.add("FOOD LOW (your threshold " + config.foodWarning() + ")");
            if (config.doseWarning() > 0 && doses < config.doseWarning()) warnings.add("POTION DOSES LOW (total)");
            if (config.combatStyle() == SlayerLabConfig.CombatStyle.RANGED && config.ammoWarning() > 0 && ammo < config.ammoWarning()) warnings.add("VISIBLE AMMO LOW");
            if (config.combatStyle() == SlayerLabConfig.CombatStyle.MAGIC && config.runeWarning() > 0 && runes < config.runeWarning()) warnings.add("VISIBLE RUNES LOW — check each required rune type");
            return String.join("\n", warnings);
        }
        String describe(SlayerLabConfig config)
        {
            String warning = warnings(config);
            return "Combat style: " + config.combatStyle() + " (change in plugin settings)\nFood items: " + food
                + "\nPotion doses: " + doses + "\nAmmo: " + ammo + "\nVisible runes: " + runes
                + "\n\n" + (warning.isEmpty() ? "No chosen threshold is crossed. This is not a combat-readiness assessment." : warning)
                + "\n\nPotion doses by item:\n" + potions + "\n\nRune stacks:\n" + runeStacks
                + "\n\nRune pouch, quiver storage, charged weapons and healing per food are not inspected. Potion totals include different potion types. Thresholds are your preferences, not mandatory supplies.";
        }
    }
    private static final Pattern DOSES = Pattern.compile("\\((\\d+)\\)$");
    static Counts count(Map<String, Integer> items, Set<String> edible, Set<String> drinkable)
    {
        Counts counts = new Counts();
        for (Map.Entry<String,Integer> item : items.entrySet())
        {
            String name = SlayerLabKnowledge.normalize(item.getKey()); int quantity = item.getValue();
            if (edible.contains(name)) counts.food += quantity;
            Matcher dose = DOSES.matcher(name);
            if (drinkable.contains(name) && dose.find())
            {
                int n = Integer.parseInt(dose.group(1));
                if (n >= 1 && n <= 6) { counts.doses += n * quantity; counts.potions.put(name, n * quantity); }
            }
            if (name.endsWith(" rune")) { counts.runes += quantity; counts.runeStacks.put(name, quantity); }
            if (name.matches(".*(?:arrow|arrows|bolt|bolts|dart|darts|javelin|javelins|throwing knife|throwing knives)(?: \\(.*\\))?$") && !name.contains("tips")) counts.ammo += quantity;
        }
        return counts;
    }
}

package lt.oneman.sync;

import java.util.*;

/** Item availability and known quest completion are explicit, never inferred from bank ownership. */
final class SlayerLabTravel
{
    static boolean slayerRing(Set<String> carried)
    { return carried.stream().anyMatch(n -> n.equals("slayer ring (eternal)") || n.matches("slayer ring \\([1-8]\\)")); }
    static String route(SlayerLabLocations.Destination d, Set<String> carried, Set<String> quests)
    {
        String n=d.name.toLowerCase(Locale.ROOT); StringBuilder out=new StringBuilder(d.name+"\n");
        if(n.contains("tower") || n.contains("fremennik") || n.contains("stronghold"))
            out.append("Slayer ring: ").append(slayerRing(carried)?"CARRIED charged/eternal ring":"NOT CARRIED").append(" → use the named dungeon teleport, then follow the entrance/chamber notes.\n");
        if(n.contains("karuulm"))
            out.append("Rada's blessing 3/4: ").append(carried.contains("rada's blessing 3")||carried.contains("rada's blessing 4")?"CARRIED — Mount Karuulm option":"NOT CARRIED").append(". Daily remaining uses of blessing 3 are not checked.\n");
        if(n.contains("taverley") || n.contains("asgar"))
            out.append("Falador teleport tablet: ").append(carried.contains("falador teleport")?"CARRIED":"NOT CARRIED").append(" → walk to the dungeon entrance; compare shortcuts with your Agility/key access.\n");
        if(n.contains("devil"))
            out.append("Ring of dueling: ").append(carried.stream().anyMatch(x->x.matches("ring of dueling \\([1-8]\\)"))?"CARRIED charged ring":"NOT CARRIED").append(" → Castle Wars, then walk south-east to the entrance.\n");
        if(n.contains("stronghold"))
            out.append("Royal seed pod: ").append(carried.contains("royal seed pod") && quests.contains("Monkey Madness II")?"CARRIED + quest completed":"requires carried pod and verified Monkey Madness II").append(" → Grand Tree, then walk to the cave.\n");
        String quest=n.contains("heroes")?"Heroes' Quest":n.contains("iorwerth")?"Song of the Elves":n.contains("harmless")?"Cabin Fever":n.contains("lighthouse")?"Horror from the Deep":n.contains("wyvern cave")?"Bone Voyage":n.contains("tower")||n.contains("spider")?"Priest in Peril":"";
        if(!quest.isEmpty()) out.append("Quest access: ").append(quest).append(" — ").append(quests.contains(quest)?"COMPLETED":"not verified completed").append("\n");
        out.append(d.access).append("\nOther teleports, fairy-ring access, POH destinations, spellbook/runes and shortcuts must be checked manually. No teleport or walking action is performed.\n\n");
        return out.toString();
    }
}

package lt.oneman.sync;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.*;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Passive preparation hints, calculated on the client thread. */
final class SlayerRequirementOverlay extends OverlayPanel
{
    static final class Row {
        final String label, status; final Color color;
        Row(String label, String status, Color color) { this.label=label;this.status=status;this.color=color; }
    }
    @Inject private OneManSyncConfig config;
    volatile List<Row> rows=Collections.emptyList();
    SlayerRequirementOverlay() { setPosition(OverlayPosition.TOP_LEFT); }
    static Row row(SlayerLabCatalog.Requirement requirement, Set<String> inventory, Set<String> equipment,
                   Map<String,Integer> bank, boolean bankKnown) {
        if(equipment.stream().anyMatch(requirement::matches))return new Row(requirement.label,"Equipped",Color.GREEN);
        if(inventory.stream().anyMatch(requirement::matches))return new Row(requirement.label,requirement.equip?"Equip":"Carried",Color.GREEN);
        if(bankKnown && bank.entrySet().stream().anyMatch(e->e.getValue()>0&&requirement.matches(e.getKey())))
            return new Row(requirement.label,"In bank",new Color(190,130,255));
        return new Row(requirement.label,bankKnown?"Missing":"Bank unknown",bankKnown?new Color(255,90,90):Color.GRAY);
    }
    @Override public Dimension render(Graphics2D graphics) {
        if(!config.slayerRequirementsOverlay()||rows.isEmpty())return null;
        panelComponent.getChildren().add(TitleComponent.builder().text("Slayer items").build());
        for(Row row:rows) {
            panelComponent.getChildren().add(LineComponent.builder().left(row.label).leftColor(row.color).build());
            panelComponent.getChildren().add(LineComponent.builder().left("  "+row.status).leftColor(row.color).build());
        }
        return super.render(graphics);
    }
}

package lt.oneman.sync;
import net.runelite.api.ChatMessageType;
import net.runelite.client.util.Text;
/** Game's own Superior message covers all Superior types, including newly added NPCs. */
final class SuperiorAlert {
 private int lastTick=Integer.MIN_VALUE;
 boolean accept(ChatMessageType type,String message,int tick) {
  if(type!=ChatMessageType.GAMEMESSAGE&&type!=ChatMessageType.SPAM)return false;
  if(message==null||!Text.removeTags(message).trim().equals("A superior foe has appeared..."))return false;
  if(lastTick!=Integer.MIN_VALUE&&tick>=lastTick&&tick-lastTick<=2)return false;
  lastTick=tick;return true;
 }
 void reset(){lastTick=Integer.MIN_VALUE;}
}

