package lt.oneman.sync;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class SlayerLabFeaturesTest
{
    @Test public void coverageIncludesHighLevelTasksAndBossAlternatives()
    {
        assertEquals(158,SlayerLabKnowledge.all().size());
        assertEquals("95",SlayerLabKnowledge.find("Hydras").level);
        assertTrue(SlayerLabAdvice.variants("Hydras").contains("Alchemical Hydra"));
        assertEquals("92",SlayerLabKnowledge.find("Araxytes").level);
        for(SlayerLabKnowledge.Entry entry:SlayerLabKnowledge.all()) assertNotNull(SlayerLabCatalog.find(entry.task));
    }
    @Test public void npcMatchingIncludesBossAndSingularButRejectsOtherTasks()
    {
        assertTrue(SlayerLabKnowledge.find("Hellhounds").matchesNpc("Cerberus"));
        assertTrue(SlayerLabKnowledge.find("Blue dragons").matchesNpc("Baby blue dragon"));
        assertTrue(SlayerLabKnowledge.find("Hydras").matchesNpc("Alchemical Hydra"));
        assertFalse(SlayerLabKnowledge.find("Blue dragons").matchesNpc("Black dragon"));
    }
    @Test public void highLevelEntrancesRespectAssignedArea()
    {
        assertEquals("Karuulm Slayer Dungeon",SlayerLabLocations.forTask("Hydras","").get(0).name);
        assertTrue(SlayerLabLocations.forTask("Hydras","Slayer Tower").isEmpty());
        assertEquals(2,SlayerLabLocations.forTask("Basilisks","").size());
        assertEquals(1,SlayerLabLocations.forTask("Basilisks","Fremennik Slayer Dungeon").size());
    }
    @Test public void quantitiesCountFoodDosesAndAmmoWithoutConfusingCharges()
    {
        Map<String,Integer> items=new HashMap<>();
        items.put("shark",4); items.put("prayer potion(4)",2); items.put("slayer ring (8)",1);
        items.put("rune arrow",100);items.put("rune arrowtips",500);items.put("death rune",80);
        SlayerLabSupplies.Counts c=SlayerLabSupplies.count(items,Collections.singleton("shark"),Collections.singleton("prayer potion(4)"));
        assertEquals(4,c.food);assertEquals(8,c.doses);assertEquals(100,c.ammo);assertEquals(80,c.runes);
    }
    @Test public void zeroThresholdDisablesWarningAndStyleSelectsResource()
    {
        SlayerLabConfig off=new SlayerLabConfig(){@Override public int foodWarning(){return 0;}};
        SlayerLabSupplies.Counts c=new SlayerLabSupplies.Counts();
        assertEquals("",c.warnings(off));
        SlayerLabConfig magic=new SlayerLabConfig(){@Override public CombatStyle combatStyle(){return CombatStyle.MAGIC;}};
        assertTrue(c.warnings(magic).contains("RUNES LOW"));assertFalse(c.warnings(magic).contains("AMMO LOW"));
    }
    @Test public void sessionSeparatesTaskCreditsFromLootKillsAndEstimatesEta()
    {
        SlayerLabJournal j=new SlayerLabJournal();j.observe("Hydras","",20,20,1000);
        j.loot(Collections.singletonMap("hydra leather",1));j.xp(300);
        j.observe("Hydras","",16,20,121000);
        assertEquals(4,j.active.credits);assertEquals(1,j.active.kills);
        assertTrue(SlayerLabJournal.metrics(j.active,121000).contains("Estimated remaining: 8 min"));
        j.observe("Hydras","",0,20,122000);j.end("Completed",122000);
        assertEquals(20,j.history.get(0).credits); assertNull(j.active);
    }
    @Test public void newTaskAndRemainingIncreaseArchiveInsteadOfMerging()
    {
        SlayerLabJournal j=new SlayerLabJournal();j.observe("Hydras","",20,0,1000);j.active.note="setup A";
        j.observe("Hydras","",30,0,2000);
        assertEquals(1,j.history.size());assertEquals("setup A",j.history.get(0).note);assertEquals(0,j.active.credits);
        j.observe("Wyrms","",20,0,3000);assertEquals(2,j.history.size());
        for(int i=0;i<60;i++){j.end("Logout",4000+i);j.observe("Wyrms","",20,0,4000+i);}
        assertEquals(50,j.history.size());
    }
    @Test public void bankPreparationDistinguishesOwnedCarriedAndEquipped()
    {
        SlayerLabAccount a=new SlayerLabAccount();SlayerLabCatalog.Guide g=SlayerLabCatalog.find("Dust devils");
        assertTrue(a.preparation(g,Collections.emptySet(),Collections.emptySet(),1000).contains("bank unknown"));
        a.bank.seen=1000;a.bank.items.put("facemask",1);
        assertTrue(a.preparation(g,Collections.emptySet(),Collections.emptySet(),61000).contains("TAKE FROM BANK"));
        assertTrue(a.preparation(g,Collections.singleton("facemask"),Collections.emptySet(),61000).contains("EQUIP"));
        assertTrue(a.preparation(g,Collections.emptySet(),Collections.singleton("facemask"),61000).contains("READY"));
        assertTrue(a.bankAge(61000).contains("1 min ago"));
    }
    @Test public void travelDoesNotTreatEmptyRingOrUnverifiedQuestAsReady()
    {
        assertFalse(SlayerLabTravel.slayerRing(Collections.singleton("slayer ring (0)")));
        assertTrue(SlayerLabTravel.slayerRing(Collections.singleton("slayer ring (8)")));
        SlayerLabLocations.Destination d=SlayerLabLocations.forTask("Bloodvelds","Stronghold Slayer Cave").get(0);
        String blocked=SlayerLabTravel.route(d,Collections.singleton("royal seed pod"),Collections.emptySet());
        assertTrue(blocked.contains("verified Monkey Madness II"));
        assertTrue(SlayerLabTravel.route(d,Collections.singleton("royal seed pod"),Collections.singleton("Monkey Madness II")).contains("CARRIED + quest completed"));
    }
    @Test public void lootGoalsSeparateBankOwnershipFromThisSession()
    {
        SlayerLabAccount.Bank bank=new SlayerLabAccount.Bank();SlayerLabJournal j=new SlayerLabJournal();
        j.observe("Hydras","",10,0,1000);j.loot(Collections.singletonMap("hydra leather",1));
        String view=SlayerLabAdvice.loot("Hydras","Hydra leather",bank,j.active);
        assertTrue(view.contains("Bank snapshot count: unknown"));assertTrue(view.contains("Observed this session: 1"));
        bank.seen=1000;bank.items.put("hydra leather",2);
        assertTrue(SlayerLabAdvice.loot("Hydras","Hydra leather",bank,j.active).contains("Bank snapshot count: 2"));
    }
    @Test public void lateInitialAmountIsRecordedAndChangedAssignmentStartsFresh()
    {
        SlayerLabJournal j=new SlayerLabJournal(); j.observe("Hydras","",20,0,1000);
        j.observe("Hydras","",19,25,2000); assertEquals(25,j.active.initial);
        j.observe("Hydras","",18,30,3000); assertEquals(1,j.history.size()); assertEquals(0,j.active.credits);
    }
    @Test public void recoveredSessionCanStopAtLastObservationWithoutOfflineTime()
    {
        SlayerLabJournal j=new SlayerLabJournal();j.observe("Hydras","",20,20,1000);
        j.observe("Hydras","",19,20,61000);
        j.end("Recovered",j.active.updated);
        assertEquals(60000,j.history.get(0).duration(99999999));
    }
}

package lt.oneman.sync;

import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class SlayerLabLocationsTest
{
    @Test public void blueDragonsHaveTwoDistinctEntrances()
    {
        List<SlayerLabLocations.Destination> choices = SlayerLabLocations.forTask("Blue dragons", "");
        assertEquals(2, choices.size());
        assertNotEquals(choices.get(0).entrance, choices.get(1).entrance);
        assertTrue(choices.get(1).access.contains("Heroes' Quest"));
    }
    @Test public void assignedAreaCannotRouteToAnotherDungeon()
    {
        List<SlayerLabLocations.Destination> choices = SlayerLabLocations.forTask("Dust devils", "the Catacombs of Kourend");
        assertEquals(1, choices.size());
        assertEquals("Catacombs of Kourend", choices.get(0).name);
        assertTrue(SlayerLabLocations.forTask("Dust devils", "unsupported assigned dungeon").isEmpty());
    }
    @Test public void knownAreaAliasesAreAccepted()
    {
        assertEquals(1, SlayerLabLocations.forTask("Bloodvelds", "Stronghold Slayer Dungeon").size());
        assertEquals(1, SlayerLabLocations.forTask("Cave horrors", "Mos Le’Harmless Cave").size());
    }
    @Test public void unknownTasksAndUnmappedLocationsDoNotInventPins()
    {
        assertTrue(SlayerLabLocations.forTask("Unknown monster", "").isEmpty());
        assertTrue(SlayerLabLocations.forTask("Lizards", "").isEmpty());
        assertTrue(SlayerLabLocations.forTask("Blue dragons", "Wilderness Slayer Cave").isEmpty());
    }
    @Test public void wildernessIsExplicitAndNotFirstChoice()
    {
        List<SlayerLabLocations.Destination> choices = SlayerLabLocations.forTask("Greater demons", "");
        assertFalse(choices.get(0).wilderness);
        assertTrue(choices.stream().anyMatch(d -> d.wilderness && d.toString().contains("WILDERNESS")));
    }
    @Test public void directionHandlesArrivalAndFloors()
    {
        WorldPoint player = new WorldPoint(3000, 3000, 0);
        assertEquals("NE", SlayerLabLocations.direction(player, new WorldPoint(3020, 3040, 0)));
        assertEquals("W", SlayerLabLocations.direction(player, new WorldPoint(2980, 3000, 0)));
        assertEquals("at entrance", SlayerLabLocations.direction(player, new WorldPoint(3003, 3002, 0)));
        assertEquals("different floor", SlayerLabLocations.direction(player, new WorldPoint(3000, 3000, 1)));
    }
    @Test public void mappedOptionsAreImmutable()
    {
        try
        {
            SlayerLabLocations.forTask("Blue dragons", "").clear();
            fail("Caller must not mutate shared destinations");
        }
        catch (UnsupportedOperationException expected) { }
    }
}

package lt.oneman.sync;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class SlayerLabPrayerTest
{
    private final SlayerLabConfig config=new SlayerLabConfig(){};
    @Test public void dosesSeparatePotionTypesAndIgnoreOtherSources()
    {
        Map<String,Integer> items=new HashMap<>();
        items.put("Prayer potion(4)",2); items.put("Prayer mix(2)",1);
        items.put("Super restore(3)",2);items.put("Super restore mix(1)",1);
        items.put("Sanfew serum(4)",2);items.put("Blighted super restore(4)",2);
        items.put("Prayer potion(0)",1);items.put("Prayer potion(4) (noted)",10);
        SlayerLabPrayer.Doses d=SlayerLabPrayer.doses(items);
        assertEquals(10,d.prayer);assertEquals(7,d.restore);assertEquals(17,d.total());
    }
    @Test public void timeNeedsStableSampleAndTracksActualObservedLoss()
    {
        SlayerLabPrayer m=new SlayerLabPrayer();m.observe(50,"PIETY");
        assertTrue(Double.isNaN(m.remainingSeconds(50)));
        for(int tick=1;tick<=20;tick++) m.observe(50-tick/10,"PIETY");
        assertEquals(288,m.remainingSeconds(48),0.001);
        assertTrue(m.describe(48,70,Collections.singletonList("PIETY"),new SlayerLabPrayer.Doses(),config).contains("~4m 48s"));
    }
    @Test public void restorationSwitchingAndEquipmentResetOldEstimate()
    {
        SlayerLabPrayer m=new SlayerLabPrayer();m.observe(50,"PIETY");
        for(int tick=1;tick<=20;tick++)m.observe(50-tick/10,"PIETY");
        assertFalse(Double.isNaN(m.remainingSeconds(48)));
        m.observe(70,"PIETY");assertTrue(Double.isNaN(m.remainingSeconds(70)));
        for(int tick=1;tick<=20;tick++)m.observe(70-tick/10,"PIETY");
        m.observe(68,"PROTECT FROM MAGIC");assertTrue(Double.isNaN(m.remainingSeconds(68)));
        m.resetEstimate();assertTrue(Double.isNaN(m.remainingSeconds(68)));
    }
    @Test public void noActivePrayerOrNoObservedDrainDoesNotInventTime()
    {
        SlayerLabPrayer m=new SlayerLabPrayer();
        for(int i=0;i<100;i++)m.observe(50,"PROTECT ITEM");
        assertTrue(Double.isNaN(m.remainingSeconds(50)));
        m.observe(50,"");assertTrue(Double.isNaN(m.remainingSeconds(50)));
        assertTrue(m.describe(50,70,Collections.emptyList(),new SlayerLabPrayer.Doses(),config).contains("no active prayers"));
        assertEquals(0,m.remainingSeconds(0),0);
    }
    @Test public void alertsFireOnceAndRearmSeparatelyAfterRecovery()
    {
        SlayerLabPrayer m=new SlayerLabPrayer();SlayerLabPrayer.Doses d=new SlayerLabPrayer.Doses();d.prayer=3;
        assertTrue(m.crossed(20,d,config).isEmpty());
        assertEquals(1,m.crossed(14,d,config).size());assertTrue(m.crossed(13,d,config).isEmpty());
        d.prayer=1;assertEquals(1,m.crossed(13,d,config).size());
        m.crossed(20,d,config);assertEquals(1,m.crossed(14,d,config).size());
        d.prayer=3;m.crossed(14,d,config);d.prayer=0;assertEquals(1,m.crossed(14,d,config).size());
    }
    @Test public void thresholdsAreStrictAndZeroDisablesAlerts()
    {
        SlayerLabPrayer m=new SlayerLabPrayer();SlayerLabPrayer.Doses d=new SlayerLabPrayer.Doses();d.restore=2;
        assertTrue(m.warnings(15,d,config).isEmpty());
        assertEquals(1,m.warnings(14,d,config).size());
        SlayerLabConfig off=new SlayerLabConfig(){@Override public int prayerPointsWarning(){return 0;} @Override public int prayerDosesWarning(){return 0;}};
        d.restore=0;assertTrue(m.warnings(0,d,off).isEmpty());assertTrue(m.crossed(0,d,off).isEmpty());
    }
    @Test public void rollingWindowDropsOldDrainAndResetClearsAlerts()
    {
        SlayerLabPrayer m=new SlayerLabPrayer();m.observe(50,"PIETY");m.observe(40,"PIETY");
        for(int i=0;i<50;i++)m.observe(40,"PIETY");
        assertTrue(Double.isNaN(m.remainingSeconds(40)));
        SlayerLabPrayer.Doses d=new SlayerLabPrayer.Doses();assertEquals(2,m.crossed(1,d,config).size());
        m.reset();assertEquals(2,m.crossed(1,d,config).size());
    }
}

package lt.oneman.sync;
import java.awt.Color;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class SlayerRequirementOverlayTest {
 @Test public void ownershipDoesNotConfuseCarriedWithEquipped() {
  SlayerLabCatalog.Requirement r=SlayerLabCatalog.find("Basilisks").requirements.get(0);
  Set<String> empty=Collections.emptySet(), shield=Collections.singleton("mirror shield");
  assertEquals("Equipped",SlayerRequirementOverlay.row(r,empty,shield,Collections.emptyMap(),false).status);
  assertEquals("Equip",SlayerRequirementOverlay.row(r,shield,empty,Collections.emptyMap(),false).status);
  assertEquals(Color.GREEN,SlayerRequirementOverlay.row(r,shield,empty,Collections.emptyMap(),false).color);
  assertEquals("In bank",SlayerRequirementOverlay.row(r,empty,empty,Collections.singletonMap("mirror shield",1),true).status);
  assertEquals("Missing",SlayerRequirementOverlay.row(r,empty,empty,Collections.singletonMap("mirror shield",0),true).status);
  assertEquals("Bank unknown",SlayerRequirementOverlay.row(r,empty,empty,Collections.emptyMap(),false).status);
  assertEquals("Missing",SlayerRequirementOverlay.row(r,empty,Collections.singleton("slayer helmet"),Collections.emptyMap(),true).status);
 }
}

package lt.oneman.sync;
